  ctx.fillStyle = '#9fb1a6'; ctx.beginPath(); ctx.moveTo(0, H * 0.7); for (let x = 0; x <= W; x += W / 12) ctx.lineTo(x, H * (0.62 + r() * 0.06)); ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
