    P.ao.overrideVisibility = function(){
      const cache = this._visibilityCache, hide = GFX.aoHide || [];
      this.scene.traverse((o) => { cache.set(o, o.visible); if (o.isPoints || o.isLine || o.isSprite || hide.includes(o) || aoSkip(o)) o.visible = false; });
    };
