    Q[fa] = toDown(fa, hd, Q[ua]);
    Q[hd] = Q[fa].clone(); for (const k of below(hd)) Q[k] = Q[fa].clone();
    const th = HB[s + '_Thigh'], ca = HB[s + '_Calf'], ft = HB[s + '_Foot'];
