    const stars = []; for (let i = 0; i < 14; i++){ const st = new THREE.Mesh(new THREE.OctahedronGeometry(0.035), new THREE.MeshBasicMaterial({ color:0xffe7a0, toneMapped:false })); st.visible = false; S.anim.add(st); stars.push(st); }
