    for (const [px, pz] of [[0.25, 0.2], [-0.25, 0.2], [0.3, -0.25], [-0.3, -0.25], [0.15, -0.6], [-0.15, -0.6]]) S.sph(0.08, m.black, px, 0.7, pz, 1, 0.5, 1, bug);
    /* AR flowers sprout around the children as they tap their screens */
