  B:{ p:[-0.096, -0.006, -0.012], into:[1, 0, 0], fingers:[0, 0.45, 1], curl:0.45 },
  Am:{ p:[0.096, -0.006, 0.0], into:[-1, 0, 0], fingers:[0, 0.45, -1], curl:0.45 },
  Bm:{ p:[-0.096, -0.006, 0.0], into:[1, 0, 0], fingers:[0, 0.45, -1], curl:0.45 }
