  const clip = add('band', new THREE.Mesh(new THREE.TorusGeometry(0.012, 0.0025, 6, 16), benchMat(0xb9c0c6, 0.3))); clip.position.set(0.235, 0.09, 0); clip.rotation.y = Math.PI / 2; partPose(clip, B(0.235, 0.055, 0.06, [0, 90, 0]));
