  /* Stick tray (root frame): columns on top, beams under them, braces at the bottom, eight lanes across */
  const T = (lane, layer, zoff, ry) => ({ p:[0.58 - 0.105 + lane * 0.03, 0.01 + layer * 0.013, -0.3 + (zoff || 0)], r:ry ? [0, ry, 0] : [90, 0, 0] });
  let lane = 0;
