    for (const [x, z] of [[-0.2, -0.15], [0.2, -0.15], [-0.2, 0.15], [0.2, 0.15]]){ const m = add(lvl ? 'col2' : 'col1', new THREE.Mesh(unitStick, stick)); S.push({ m, ax:x, bx:x, la:lvl, lb:lvl + 1, z }); m.userData.binPose = T(lane, 2, -0.1); lane++; }
