  SV.sieves.forEach((s) => { const k = s.i >= 6 ? s.i - 6 : s.i, pile = s.i >= 6 ? H.pileA : H.pileB; svPut(s.g, [pile[0], pile[1] + 0.014 + k * 0.028, pile[2]]); s.g.userData.held.visible = false; });
