  svPour(C, SV.rp[0], [SV.x, SV.y, -7.85], [33.5, 1.12, -8.06], 0.93, 1.2, (u) => { SV.pans[0] = f0 * 0.5 * (1 - u); SV.frac = f0 * 0.5 * u; svSand(); }, { lip:[0.105, 0.04, 0], sz:6 });
