  TT.liquid = new THREE.Mesh(new THREE.CylinderGeometry(0.0062, 0.0062, 1, 12), TT.liqMat); TT.liquid.position.set(bx, 0, bz); g.add(TT.liquid);
  TT.bTop = bTop; TT.bBot = bBot;
