  pickBox(0.12, 0.08, 0.1, bx, bBot, bz, { station:'titration', act:'drop' });
  pickBox(0.14, 0.2, 0.14, TT.x, TT.y + 0.14, TT.z, { station:'titration', act:'flask' });
