const ride = { on:null, gentle:false, phase:'', t:0, s:0, v:0, y:1, u:0, paused:false, exiting:false, look:{ yaw:0, pitch:0, at:0 }, cap:null, stat:null, fact:-1, lift:0, dyaw:null, dpitch:null };
