  if (vn < 0){ const e = b.soft ? 0.05 : Math.min(e0, b.e + 0.2); v.x -= (1 + e) * vn * nx; v.y -= (1 + e) * vn * ny; v.z -= (1 + e) * vn * nz; if (b.soft) v.multiplyScalar(0.55); }
