      const [t0, a] = seg[i], [t1, b] = seg[i + 1], u = clamp((t - t0) / (t1 - t0), 0, 1);
      spBlend(o, spD(L, a, 1), spD(L, b, 1), i === 1 ? u * u : spEase(u));
