/* Ground stance: pelvis height from the pose, plus any hop */
function keeperGround(dy, hop){ const K = KEEP; K.com.set(K.pos.x, (0.895 + dy) * K.fig.S + (hop || 0), K.pos.z); K.roll = 0; }
