  const K = KEEP, dx = tx - K.pos.x, dz = tz - K.pos.z, d = Math.hypot(dx, dz), want = d > 0.02 ? Math.min(vmax, d * 4) : 0;
  const k = 1 - Math.exp(-dt * 10), wx = d > 1e-4 ? dx / d * want : 0, wz = d > 1e-4 ? dz / d * want : 0;
