  f.all[HB.L_Hand].getWorldPosition(l); f.all[HB.L_Finger2].getWorldPosition(_kv); l.lerp(_kv, 0.75);
  f.all[HB.R_Hand].getWorldPosition(r); f.all[HB.R_Finger2].getWorldPosition(_kv); r.lerp(_kv, 0.75);
