    if (ptr.painting){ paintMove(e.clientX, e.clientY); return; }
    if (!ptr.moved && Math.hypot(e.clientX - ptr.x, e.clientY - ptr.y) > 7){ ptr.moved = true; ui.scene.classList.add('dragging'); ui.tag.hidden = true; }
